USER_DATA_DIR = os.path.expanduser("~/Desktop/时尚项目/豆包浏览器数据")

with sync_playwright() as p:
    context = p.chromium.launch_persistent_context(
        USER_DATA_DIR, headless=False,
        viewport={'width': 1400, 'height': 900}, locale='zh-CN',
        args=['--disable-blink-features=AutomationControlled'],
    )
    context.add_init_script("""
        Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
    """)
    page = context.new_page()

    page.goto("https://www.doubao.com/chat/", wait_until='domcontentloaded', timeout=20000)
    page.wait_for_timeout(3000)

    # 等待登录
    if page.locator('text=登录').first.is_visible():
        print("⚠️ 请登录...")
        try:
            page.wait_for_selector('text=登录', state='hidden', timeout=120000)
        except:
            pass
    page.wait_for_timeout(2000)

    # 点击图像生成
    page.locator('text=图像生成').first.click()
    page.wait_for_timeout(3000)

    # === 查找"生成"元素的完整结构 ===
    print("=== 所有包含'生成'文字的元素 ===")
    gen_elems = page.locator('text=生成').all()
    for i, elem in enumerate(gen_elems):
        try:
            tag = elem.evaluate('el => el.tagName')
            text = elem.text_content().strip()
            cls = elem.get_attribute('class') or ''
            visible = elem.is_visible()
            # 获取父级
            parent_tag = elem.evaluate('el => el.parentElement.tagName')
            parent_cls = elem.evaluate('el => el.parentElement.className') or ''
            # 坐标
            box = elem.bounding_box()

            print(f"\n#{i}: <{tag}> text='{text}' visible={visible}")
            print(f"    class={cls[:80]}")
            print(f"    parent: <{parent_tag}> class={parent_cls[:80]}")
            if box:
                print(f"    position: x={box['x']:.0f} y={box['y']:.0f} w={box['width']:.0f} h={box['height']:.0f}")

            # 再往上看一层
            grandparent_tag = elem.evaluate('el => el.parentElement?.parentElement?.tagName')
            grandparent_cls = elem.evaluate('el => el.parentElement?.parentElement?.className') or ''
            print(f"    grandparent: <{grandparent_tag}> class={grandparent_cls[:80]}")
        except:
            pass

    # === 查找输入区域附近的图标按钮 ===
    print("\n=== 查找 ProseMirror 编辑器附近的按钮 ===")
    editor_area = page.locator('.ProseMirror').first
    if editor_area.is_visible():
        # 向上找容器
        # 通常输入区域的结构是: 外层容器 > 输入框容器 > 编辑器 + 按钮
        # 找到包含编辑器的较大容器
        container = editor_area.evaluate("""el => {
            let p = el.parentElement;
            for (let i = 0; i < 6; i++) {
                if (!p) break;
                // 找这个容器内的所有按钮
                let buttons = p.querySelectorAll('button');
                if (buttons.length > 0) {
                    return {
                        level: i+1,
                        tag: p.tagName,
                        class: p.className,
                        buttonCount: buttons.length,
                        buttonDetails: Array.from(buttons).slice(0,10).map(b => ({
                            text: b.textContent.trim().slice(0,40),
                            aria: b.getAttribute('aria-label') || '',
                            title: b.getAttribute('title') || '',
                            cls: b.className.slice(0,60),
                            svgCount: b.querySelectorAll('svg').length,
                        }))
                    };
                }
                p = p.parentElement;
            }
            return null;
        }""")
        print(f"   编辑器容器 (level={container['level']}): <{container['tag']}>")
        print(f"   找到 {container['buttonCount']} 个按钮:")
        for btn in container['buttonDetails']:
            print(f"     ▸ text='{btn['text']}' aria='{btn['aria']}' svg={btn['svgCount']} class={btn['cls']}")

    # 截图
    page.screenshot(path=os.path.expanduser("~/Desktop/时尚项目/豆包截图_生图v3.png"))
    print("\n📸 截图已保存")

    page.wait_for_timeout(5000)
    context.close()

