#!/usr/bin/env python3
"""
豆包自动生图脚本 v4
关键发现：
- 输入框是 ProseMirror 富文本编辑器 (data-placeholder="描述你想要的图片")
- 发送按钮是输入框容器内的第一个 SVG 图标按钮（无文字标签）
- 生成结果在聊天消息区域
"""

import os, sys, json, time, subprocess, urllib.request, base64
from playwright.sync_api import sync_playwright

USER_DATA_DIR = os.path.expanduser("~/Desktop/时尚项目/豆包浏览器数据")
OUTFIT_BASE = os.path.expanduser("~/Desktop/时尚项目/每日穿搭")

def find_latest_outfit():
    dirs = sorted([d for d in os.listdir(OUTFIT_BASE)
                   if os.path.isdir(os.path.join(OUTFIT_BASE, d)) and not d.startswith('.')])
    return os.path.join(OUTFIT_BASE, dirs[-1]) if dirs else None

def collect_images(doubao_dir):
    images = []
    for f in sorted(os.listdir(doubao_dir)):
        if f.startswith("人物_") and f.lower().endswith(('.jpg','.jpeg','.png')):
            images.append(os.path.join(doubao_dir, f))
            break
    for prefix in ['上衣_', '下装_', '鞋子_']:
        for f in sorted(os.listdir(doubao_dir)):
            if f.startswith(prefix) and f.lower().endswith(('.jpg','.jpeg','.png')):
                images.append(os.path.join(doubao_dir, f))
    for f in sorted(os.listdir(doubao_dir)):
        if f.startswith('配饰_') and f.lower().endswith(('.jpg','.jpeg','.png')):
            images.append(os.path.join(doubao_dir, f))
    return images

def load_prompt(doubao_dir):
    prompt_file = os.path.join(doubao_dir, "豆包提示词.txt")
    if os.path.exists(prompt_file):
        with open(prompt_file, 'r', encoding='utf-8') as f:
            return f.read().strip()
    return None

def find_send_button(page):
    """找到输入区域中的发送按钮（SVG图标按钮）"""
    # 方法1：在 ProseMirror 编辑器附近找 SVG 按钮
    editor = page.locator('.ProseMirror').first
    if editor.is_visible():
        # 向上找包含按钮的容器
        container = editor.evaluate("""el => {
            let p = el.parentElement;
            for (let i = 0; i < 8; i++) {
                if (!p) break;
                let buttons = p.querySelectorAll('button');
                for (let btn of buttons) {
                    // 找只有SVG没有文字的按钮（发送按钮）
                    if (btn.querySelector('svg') && btn.textContent.trim() === '') {
                        return { found: true, index: Array.from(p.querySelectorAll('button')).indexOf(btn) };
                    }
                }
                p = p.parentElement;
            }
            return { found: false };
        }""")

        if container.get('found'):
            # 重新找这个按钮
            editor2 = page.locator('.ProseMirror').first
            parent = editor2.evaluate("""el => {
                let p = el.parentElement;
                for (let i = 0; i < 8; i++) {
                    if (!p) break;
                    let buttons = p.querySelectorAll('button');
                    if (buttons.length > 0) return i;
                    p = p.parentElement;
                }
                return 3;
            }""")

            # 向上到容器
            container_elem = editor2
            for _ in range(parent):
                container_elem = container_elem.locator('..')

            # 在容器中找SVG按钮
            all_btns = container_elem.locator('button').all()
            for btn in all_btns:
                try:
                    svg_count = btn.locator('svg').count()
                    text = btn.text_content().strip()
                    if svg_count > 0 and not text:
                        return btn
                except:
                    pass

    return None

def main():
    print("=" * 60)
    print("🤖 豆包自动生图助手 v4")
    print("=" * 60)

    outfit_dir = find_latest_outfit()
    if not outfit_dir:
        print("❌ 未找到穿搭文件夹")
        return

    doubao_dir = os.path.join(outfit_dir, "豆包生图")
    if not os.path.exists(doubao_dir):
        doubao_dir = outfit_dir

    print(f"\n📁 {os.path.basename(outfit_dir)}")
    images = collect_images(doubao_dir)
    prompt = load_prompt(doubao_dir)
    print(f"📷 {len(images)} 张 | 📝 {'✅' if prompt else '❌'}")

    if not images or not prompt:
        return

    os.makedirs(USER_DATA_DIR, exist_ok=True)

    with sync_playwright() as p:
        context = p.chromium.launch_persistent_context(
            USER_DATA_DIR, headless=False,
            viewport={'width': 1400, 'height': 900}, locale='zh-CN',
            args=['--disable-blink-features=AutomationControlled'],
        )
        context.add_init_script("""
            Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
        """)
        page = context.new_page()

        # ===== 1. 打开豆包 =====
        print("\n📋 1/7 打开豆包...")
        page.goto("https://www.doubao.com/chat/", wait_until='domcontentloaded', timeout=20000)
        page.wait_for_timeout(3000)

        if page.locator('text=登录').first.is_visible():
            print("   ⚠️ 需要登录，请在浏览器中完成...")
            page.locator('text=登录').first.click()
            try:
                page.wait_for_selector('text=登录', state='hidden', timeout=120000)
                print("   ✅ 登录完成")
            except:
                pass
        else:
            print("   ✅ 已登录")
        page.wait_for_timeout(2000)

        # ===== 2. 切换到图像生成 =====
        print("\n📋 2/7 进入图像生成模式...")
        try:
            page.locator('text=图像生成').first.click(timeout=5000)
            page.wait_for_timeout(2000)
            print("   ✅ 已切换")
        except:
            print("   ⚠️ 请手动点击「图像生成」")
            page.wait_for_timeout(10000)

        # ===== 3. 上传图片 =====
        print("\n📋 3/7 上传图片...")
        try:
            file_input = page.locator('input[type="file"]').first
            file_input.set_input_files(images)
            print(f"   ✅ {len(images)} 张已上传")
        except Exception as e:
            print(f"   ❌ {e}")
            for img in images:
                try:
                    page.locator('input[type="file"]').first.set_input_files(img)
                    print(f"   ✅ {os.path.basename(img)[:40]}")
                    page.wait_for_timeout(600)
                except:
                    pass

        # 等待图片上传处理
        print("   等待上传处理...")
        page.wait_for_timeout(4000)

        # ===== 4. 填写提示词 =====
        print("\n📋 4/7 填写提示词到 ProseMirror 编辑器...")

        # 定位 ProseMirror 编辑器
        editor = page.locator('.ProseMirror').first
        if editor.is_visible():
            editor.click()
            page.wait_for_timeout(500)
            # 清空现有内容
            editor.evaluate('el => el.innerHTML = ""')
            page.wait_for_timeout(300)
            # 逐字输入
            editor.type(prompt, delay=15)
            print(f"   ✅ 提示词已输入 ({len(prompt)}字符)")
        else:
            print("   ❌ 未找到编辑器")
            subprocess.run(['pbcopy'], input=prompt.encode('utf-8'))
            print("   📋 已复制到剪贴板 (Cmd+V)")
            page.wait_for_timeout(10000)

        page.wait_for_timeout(1500)

        # ===== 5. 找到发送按钮 =====
        print("\n📋 5/7 定位发送按钮...")
        send_btn = find_send_button(page)

        if send_btn:
            print("   ✅ 找到了发送按钮（SVG图标按钮）")
        else:
            print("   ⚠️ 未找到，尝试所有SVG按钮...")
            # 备用：遍历所有按钮找SVG图标
            all_btns = page.locator('button').all()
            for btn in all_btns:
                try:
                    if btn.locator('svg').count() > 0 and not btn.text_content().strip():
                        # 排除已知不是发送按钮的
                        box = btn.bounding_box()
                        if box and box['y'] > 400:  # 在下半部分
                            send_btn = btn
                            print(f"   ✅ 备选发送按钮: y={box['y']:.0f}")
                            break
                except:
                    pass

        # ===== 6. 点击发送 =====
        print("\n📋 6/7 点击发送...")
        if send_btn:
            try:
                send_btn.click()
                print("   ✅ 已点击发送按钮")
            except Exception as e:
                print(f"   ❌ 点击失败: {e}")
                print("   尝试按 Enter 键...")
                page.keyboard.press('Enter')
        else:
            print("   ⚠️ 尝试 Enter 键...")
            page.keyboard.press('Enter')

        # ===== 7. 等待生成并下载 =====
        print("\n📋 7/7 等待生成并下载...")

        download_dir = os.path.join(outfit_dir, "上身效果")
        os.makedirs(download_dir, exist_ok=True)

        # 监听自动下载
        downloaded = []
        def on_download(download):
            fname = f"上身效果_{len(downloaded)+1}.png"
            spath = os.path.join(download_dir, fname)
            download.save_as(spath)
            downloaded.append(spath)
            print(f"   ✅ 下载: {fname}")
        page.on('download', on_download)

        # 等待并检测生成的图片
        start = time.time()
        max_wait = 300
        last_count = 0

        while time.time() - start < max_wait:
            page.wait_for_timeout(5000)
            elapsed = int(time.time() - start)

            # 查找聊天区域中新生成的图片
            try:
                # 获取页面中所有img元素
                img_urls = page.evaluate("""() => {
                    const imgs = document.querySelectorAll('img');
                    const urls = [];
                    for (const img of imgs) {
                        const src = img.src;
                        // 跳过小图标和头像
                        if (src && img.naturalWidth > 150 && !src.includes('favicon') && !src.includes('logo')) {
                            urls.push({src: src, w: img.naturalWidth, h: img.naturalHeight});
                        }
                    }
                    return urls;
                }""")

                if img_urls and len(img_urls) > last_count:
                    print(f"   🔍 发现 {len(img_urls)} 张大图 (已等{elapsed}s)")
                    last_count = len(img_urls)

                    # 下载新图片
                    for i, img_info in enumerate(img_urls):
                        url = img_info['src']
                        if any(url == d.get('src', '') for d in downloaded):
                            continue
                        try:
                            filename = f"上身效果_{len(downloaded)+1}.png"
                            save_path = os.path.join(download_dir, filename)
                            if url.startswith('data:'):
                                data_b64 = url.split(',', 1)[1]
                                with open(save_path, 'wb') as f:
                                    f.write(base64.b64decode(data_b64))
                            else:
                                urllib.request.urlretrieve(url, save_path)
                            downloaded.append({'src': url, 'path': save_path})
                            print(f"   ✅ {filename} ({img_info['w']}x{img_info['h']})")
                        except Exception as e:
                            pass

                    # 如果检测到足够数量的图片且等待了足够久
                    if len(downloaded) >= 1 and elapsed > 30:
                        page.wait_for_timeout(3000)
                        break

            except Exception as e:
                pass

            # 每30秒报告进度
            if elapsed % 30 < 5:
                print(f"   ⏳ 等待中... ({elapsed}s)")

        # ===== 完成 =====
        print(f"\n{'=' * 60}")
        actual = [d for d in downloaded if isinstance(d, dict) and 'path' in d]
        if actual:
            print(f"✅ 生图完成！共 {len(actual)} 张")
            for d in actual:
                fname = os.path.basename(d['path'])
                fsize = os.path.getsize(d['path']) if os.path.exists(d['path']) else 0
                print(f"   ▸ {fname} ({fsize//1024}KB)")
            print(f"📁 {download_dir}")
        else:
            print(f"⚠️ 自动下载未成功")
            print(f"   请手动保存图片到: {download_dir}")

        print(f"\n⏳ 浏览器保持 60 秒，可手动下载...")
        page.wait_for_timeout(60000)
        context.close()

if __name__ == '__main__':
    main()

