            print("   ⚠️ 请手动点击「图像生成」")
            page.wait_for_timeout(10000)

        # ===== 3. 上传图片 =====
        print("\n📋 3/7 上传图片...")
        try:
            file_input = page.locator('input[type="file"]').first
            file_input.set_input_files(images)
            print(f"   ✅ {len(images)} 张已上传")
        except Exception as e:
            print(f"   ❌ {e}")
            for img in images:
                try:
                    page.locator('input[type="file"]').first.set_input_files(img)
                    print(f"   ✅ {os.path.basename(img)[:40]}")
                    page.wait_for_timeout(600)
                except:
                    pass

        # 等待图片上传处理
        print("   等待上传处理...")
        page.wait_for_timeout(4000)

        # ===== 4. 填写提示词 =====
        print("\n📋 4/7 填写提示词到 ProseMirror 编辑器...")

        # 定位 ProseMirror 编辑器
        editor = page.locator('.ProseMirror').first
        if editor.is_visible():
            editor.click()
            page.wait_for_timeout(500)
            # 清空现有内容
            editor.evaluate('el => el.innerHTML = ""')
            page.wait_for_timeout(300)
            # 逐字输入
            editor.type(prompt, delay=15)
            print(f"   ✅ 提示词已输入 ({len(prompt)}字符)")
        else:
            print("   ❌ 未找到编辑器")
            subprocess.run(['pbcopy'], input=prompt.encode('utf-8'))
            print("   📋 已复制到剪贴板 (Cmd+V)")
            page.wait_for_timeout(10000)

        page.wait_for_timeout(1500)

        # ===== 5. 找到发送按钮 =====
        print("\n📋 5/7 定位发送按钮...")
        send_btn = find_send_button(page)

        if send_btn:
            print("   ✅ 找到了发送按钮（SVG图标按钮）")
        else:
            print("   ⚠️ 未找到，尝试所有SVG按钮...")
            # 备用：遍历所有按钮找SVG图标
            all_btns = page.locator('button').all()
            for btn in all_btns:
                try:
                    if btn.locator('svg').count() > 0 and not btn.text_content().strip():
                        # 排除已知不是发送按钮的
                        box = btn.bounding_box()
                        if box and box['y'] > 400:  # 在下半部分
                            send_btn = btn
                            print(f"   ✅ 备选发送按钮: y={box['y']:.0f}")
                            break
                except:
                    pass

        # ===== 6. 点击发送 =====
        print("\n📋 6/7 点击发送...")
        if send_btn:
            try:
                send_btn.click()
                print("   ✅ 已点击发送按钮")
            except Exception as e:
                print(f"   ❌ 点击失败: {e}")
                print("   尝试按 Enter 键...")
                page.keyboard.press('Enter')
        else:
            print("   ⚠️ 尝试 Enter 键...")
            page.keyboard.press('Enter')

        # ===== 7. 等待生成并下载 =====
        print("\n📋 7/7 等待生成并下载...")

        download_dir = os.path.join(outfit_dir, "上身效果")
        os.makedirs(download_dir, exist_ok=True)

        # 监听自动下载
        downloaded = []
        def on_download(download):
            fname = f"上身效果_{len(downloaded)+1}.png"
            spath = os.path.join(download_dir, fname)
            download.save_as(spath)
            downloaded.append(spath)
            print(f"   ✅ 下载: {fname}")
        page.on('download', on_download)

        # 等待并检测生成的图片
        start = time.time()
        max_wait = 300
        last_count = 0

        while time.time() - start < max_wait:
            page.wait_for_timeout(5000)
            elapsed = int(time.time() - start)

            # 查找聊天区域中新生成的图片
            try:
                # 获取页面中所有img元素
                img_urls = page.evaluate("""() => {
                    const imgs = document.querySelectorAll('img');
                    const urls = [];
                    for (const img of imgs) {
                        const src = img.src;
                        // 跳过小图标和头像
                        if (src && img.naturalWidth > 150 && !src.includes('favicon') && !src.includes('logo')) {
                            urls.push({src: src, w: img.naturalWidth, h: img.naturalHeight});
                        }
                    }
                    return urls;
                }""")

                if img_urls and len(img_urls) > last_count:
                    print(f"   🔍 发现 {len(img_urls)} 张大图 (已等{elapsed}s)")
                    last_count = len(img_urls)

                    # 下载新图片
                    for i, img_info in enumerate(img_urls):
                        url = img_info['src']
                        if any(url == d.get('src', '') for d in downloaded):
                            continue
                        try:
                            filename = f"上身效果_{len(downloaded)+1}.png"
                            save_path = os.path.join(download_dir, filename)
                            if url.startswith('data:'):
                                data_b64 = url.split(',', 1)[1]
                                with open(save_path, 'wb') as f:
                                    f.write(base64.b64decode(data_b64))
                            else:
                                urllib.request.urlretrieve(url, save_path)
                            downloaded.append({'src': url, 'path': save_path})
                            print(f"   ✅ {filename} ({img_info['w']}x{img_info['h']})")
                        except Exception as e:
                            pass

                    # 如果检测到足够数量的图片且等待了足够久
                    if len(downloaded) >= 1 and elapsed > 30:
                        page.wait_for_timeout(3000)
                        break

            except Exception as e:
                pass

            # 每30秒报告进度
            if elapsed % 30 < 5:
                print(f"   ⏳ 等待中... ({elapsed}s)")

        # ===== 完成 =====
        print(f"\n{'=' * 60}")
        actual = [d for d in downloaded if isinstance(d, dict) and 'path' in d]
        if actual:
            print(f"✅ 生图完成！共 {len(actual)} 张")
            for d in actual:
                fname = os.path.basename(d['path'])
                fsize = os.path.getsize(d['path']) if os.path.exists(d['path']) else 0
                print(f"   ▸ {fname} ({fsize//1024}KB)")
            print(f"📁 {download_dir}")
        else:
            print(f"⚠️ 自动下载未成功")
            print(f"   请手动保存图片到: {download_dir}")

        print(f"\n⏳ 浏览器保持 60 秒，可手动下载...")
        page.wait_for_timeout(60000)
        context.close()

if __name__ == '__main__':
    main()

