#!/usr/bin/env python3
"""
豆包自动生图脚本 v5 - 最终版
修复：
- 强制点击发送按钮（绕过遮罩）
- 过滤小图标（只下载 >800px 的生成图）
- 更智能的等待逻辑
"""

import os, sys, json, time, subprocess, urllib.request, base64
from playwright.sync_api import sync_playwright

USER_DATA_DIR = os.path.expanduser("~/Desktop/时尚项目/豆包浏览器数据")
OUTFIT_BASE = os.path.expanduser("~/Desktop/时尚项目/每日穿搭")

def find_latest_outfit():
    dirs = sorted([d for d in os.listdir(OUTFIT_BASE)
                   if os.path.isdir(os.path.join(OUTFIT_BASE, d)) and not d.startswith('.')])
    return os.path.join(OUTFIT_BASE, dirs[-1]) if dirs else None

def collect_images(doubao_dir):
    images = []
    for f in sorted(os.listdir(doubao_dir)):
        if f.startswith("人物_") and f.lower().endswith(('.jpg','.jpeg','.png')):
            images.append(os.path.join(doubao_dir, f))
            break
    for prefix in ['上衣_', '下装_', '鞋子_']:
        for f in sorted(os.listdir(doubao_dir)):
            if f.startswith(prefix) and f.lower().endswith(('.jpg','.jpeg','.png')):
                images.append(os.path.join(doubao_dir, f))
    for f in sorted(os.listdir(doubao_dir)):
        if f.startswith('配饰_') and f.lower().endswith(('.jpg','.jpeg','.png')):
            images.append(os.path.join(doubao_dir, f))
    return images

def load_prompt(doubao_dir):
    prompt_file = os.path.join(doubao_dir, "豆包提示词.txt")
    if os.path.exists(prompt_file):
        with open(prompt_file, 'r', encoding='utf-8') as f:
            return f.read().strip()
    return None

def main():
    print("=" * 60)
    print("🤖 豆包自动生图助手 v5 (最终版)")
    print("=" * 60)

    outfit_dir = find_latest_outfit()
    if not outfit_dir:
        print("❌ 未找到穿搭文件夹")
        return

    doubao_dir = os.path.join(outfit_dir, "豆包生图")
    if not os.path.exists(doubao_dir):
        doubao_dir = outfit_dir

    print(f"\n📁 {os.path.basename(outfit_dir)}")

    images = collect_images(doubao_dir)
    prompt = load_prompt(doubao_dir)
    print(f"📷 {len(images)} 张图片")
    print(f"📝 提示词: {'✅' if prompt else '❌'}")

    if not images or not prompt:
        return

    os.makedirs(USER_DATA_DIR, exist_ok=True)

    with sync_playwright() as p:
        context = p.chromium.launch_persistent_context(
            USER_DATA_DIR, headless=False,
            viewport={'width': 1400, 'height': 900}, locale='zh-CN',
            args=['--disable-blink-features=AutomationControlled'],
        )
        context.add_init_script("""
            Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
        """)
        page = context.new_page()

        # 1. 打开豆包
        print("\n📋 1/6 打开豆包...")
        page.goto("https://www.doubao.com/chat/", wait_until='domcontentloaded', timeout=20000)
        page.wait_for_timeout(3000)

        if page.locator('text=登录').first.is_visible():
            print("   ⚠️ 需要登录，请在浏览器中完成...")
            page.locator('text=登录').first.click()
            try:
                page.wait_for_selector('text=登录', state='hidden', timeout=120000)
                print("   ✅ 登录完成")
            except:
                pass
        else:
            print("   ✅ 已登录")
        page.wait_for_timeout(2000)

        # 2. 图像生成模式
        print("\n📋 2/6 进入图像生成...")
        try:
            page.locator('text=图像生成').first.click(timeout=5000)
            page.wait_for_timeout(2500)
            print("   ✅ 已切换")
        except:
            print("   ⚠️ 请手动点击「图像生成」")
            page.wait_for_timeout(10000)

        # 3. 上传图片
        print("\n📋 3/6 上传图片...")
        try:
            page.locator('input[type="file"]').first.set_input_files(images)
            print(f"   ✅ {len(images)} 张已上传")
        except Exception as e:
            print(f"   ❌ 批量失败: {e}")
            for img in images:
                try:
                    page.locator('input[type="file"]').first.set_input_files(img)
                    print(f"   ✅ {os.path.basename(img)[:40]}")
                    page.wait_for_timeout(500)
                except:
                    pass

        print("   等待上传完成...")
        page.wait_for_timeout(5000)

        # 4. 填写提示词
        print("\n📋 4/6 填写提示词...")
        editor = page.locator('.ProseMirror').first
        if editor.is_visible():
            editor.click()
            page.wait_for_timeout(500)
            editor.evaluate('el => el.innerHTML = ""')
            page.wait_for_timeout(300)
            editor.type(prompt, delay=10)
            print(f"   ✅ 已输入 ({len(prompt)}字符)")
        else:
            print("   ❌ 未找到编辑器")
            subprocess.run(['pbcopy'], input=prompt.encode('utf-8'))
            print("   📋 已复制到剪贴板")
            page.wait_for_timeout(5000)

        page.wait_for_timeout(2000)

        # 5. 点击发送 - 多种方式并行
        print("\n📋 5/6 触发生成...")
        sent = False

        # 方式1：强制点击 send-message-action-bar
        try:
            action_bar = page.locator('[data-foundation-type="send-message-action-bar"]').first
            if action_bar.is_visible():
                action_bar.click(force=True)
                sent = True
                print("   ✅ 点击了 send-message-action-bar")
        except:
            pass

        # 方式2：强制点击 send 按钮
        if not sent:
            try:
                # 找到所有按钮中带SVG且在底部的
                btns = page.locator('button').all()
                for btn in btns:
                    try:
                        box = btn.bounding_box()
                        svg_count = btn.locator('svg').count()
                        text = btn.text_content().strip()
                        if box and svg_count > 0 and not text and box['y'] > 400:
                            btn.click(force=True, timeout=3000)
                            sent = True
                            print(f"   ✅ 强制点击发送按钮 (y={box['y']:.0f})")
                            break
                    except:
                        continue
            except:
                pass

        # 方式3：Cmd+Enter (Mac)
        if not sent:
            print("   尝试 Cmd+Enter...")
            page.keyboard.press('Meta+Enter')
            sent = True

        # 方式4：普通 Enter
        if not sent:
            print("   尝试 Enter...")
            page.keyboard.press('Enter')
            sent = True

        # 6. 等待生成并下载
        print("\n📋 6/6 等待生成结果...")
        download_dir = os.path.join(outfit_dir, "上身效果")
        os.makedirs(download_dir, exist_ok=True)

        downloaded = []
        def on_download(download):
            fname = f"上身效果_{len(downloaded)+1}.png"
            spath = os.path.join(download_dir, fname)
            try:
                download.save_as(spath)
                downloaded.append(spath)
                print(f"   ✅ 浏览器下载: {fname}")
            except:
                pass
        page.on('download', on_download)

        start = time.time()
        max_wait = 360  # 6分钟
        last_large_count = 0
        no_new_images_since = 0

        while time.time() - start < max_wait:
            page.wait_for_timeout(5000)
            elapsed = int(time.time() - start)

            # 查找大尺寸图片（生成图 >800px）
            try:
                large_imgs = page.evaluate("""() => {
                    const imgs = document.querySelectorAll('img');
                    const results = [];
                    for (const img of imgs) {
                        if (img.naturalWidth > 800 || img.naturalHeight > 800) {
                            const src = img.src || img.getAttribute('src') || '';
                            if (src && !src.includes('favicon') && !src.includes('logo.png')) {
                                results.push({
                                    src: src,
                                    w: img.naturalWidth,
                                    h: img.naturalHeight,
                                    alt: img.alt || ''
                                });
                            }
                        }
                    }
                    return results;
                }""")

                if large_imgs and len(large_imgs) > last_large_count:
                    print(f"   🔍 发现 {len(large_imgs)} 张大尺寸图 (已等{elapsed}s)")
                    last_large_count = len(large_imgs)
                    no_new_images_since = 0

                    for i, img_info in enumerate(large_imgs):
                        url = img_info['src']
                        # 跳过已下载的
                        if any(url == d.get('src', '') for d in downloaded):
                            continue
                        try:
                            filename = f"上身效果_{len(downloaded)+1}.png"
                            save_path = os.path.join(download_dir, filename)

                            if url.startswith('data:'):
                                data_b64 = url.split(',', 1)[1]
                                with open(save_path, 'wb') as f:
                                    f.write(base64.b64decode(data_b64))
                            elif url.startswith('blob:'):
                                # blob URL需要特殊处理
                                print(f"   ⚠️ blob URL，尝试右键保存...")
                                continue
                            else:
                                # 添加referer避免防盗链
                                req = urllib.request.Request(url, headers={
                                    'Referer': 'https://www.doubao.com/',
                                    'User-Agent': 'Mozilla/5.0'
                                })
                                with urllib.request.urlopen(req, timeout=30) as resp:
                                    with open(save_path, 'wb') as f:
                                        f.write(resp.read())

                            dl = {'src': url, 'path': save_path}
                            downloaded.append(dl)
                            print(f"   ✅ {filename} ({img_info['w']}x{img_info['h']}px)")
                        except Exception as e:
                            pass
                else:
                    no_new_images_since += 5

                # 停止条件：有图片且连续30秒没新图
                if downloaded and no_new_images_since >= 30:
                    print(f"   ✅ 生成完成（{elapsed}秒）")
                    break

            except Exception as e:
                pass

            # 每30秒报告
            if elapsed > 0 and elapsed % 30 < 5:
                print(f"   ⏳ {elapsed}秒... (已下载{len(downloaded)}张)")

            # 检查生成是否在进行中
            try:
                # 豆包可能在显示"生成中"动画
                generating = page.locator('[class*="generating"], [class*="loading"], text=正在生成').first
                if generating.is_visible():
                    print(f"   🎨 豆包正在生成中...")
            except:
                pass

        # 报告
        print(f"\n{'=' * 60}")
        actual = [d for d in downloaded if isinstance(d, dict) and 'path' in d]
        if actual:
            print(f"✅ 生图完成！共 {len(actual)} 张")
            for d in actual:
                path = d['path']
                if os.path.exists(path):
                    size_kb = os.path.getsize(path) // 1024
                    print(f"   ▸ {os.path.basename(path)} ({size_kb}KB)")
            print(f"📁 {download_dir}")
        else:
            print(f"⚠️ 未检测到大尺寸生成图")
            print(f"   请手动保存图片到: {download_dir}")

        print(f"\n⏳ 浏览器保持 60 秒，可手动操作...")
        page.wait_for_timeout(60000)
        context.close()

if __name__ == '__main__':
    main()

