                    for (const img of imgs) {
                        if (img.naturalWidth > 800 || img.naturalHeight > 800) {
                            const src = img.src || img.getAttribute('src') || '';
                            if (src && !src.includes('favicon') && !src.includes('logo.png')) {
                                results.push({
                                    src: src,
                                    w: img.naturalWidth,
                                    h: img.naturalHeight,
                                    alt: img.alt || ''
                                });
                            }
                        }
                    }
                    return results;
                }""")

