                    last_large_count = len(large_imgs)
                    no_new_images_since = 0

                    for i, img_info in enumerate(large_imgs):
                        url = img_info['src']
                        # 跳过已下载的
                        if any(url == d.get('src', '') for d in downloaded):
                            continue
                        try:
                            filename = f"上身效果_{len(downloaded)+1}.png"
                            save_path = os.path.join(download_dir, filename)

                            if url.startswith('data:'):
                                data_b64 = url.split(',', 1)[1]
                                with open(save_path, 'wb') as f:
                                    f.write(base64.b64decode(data_b64))
                            elif url.startswith('blob:'):
                                # blob URL需要特殊处理
                                print(f"   ⚠️ blob URL，尝试右键保存...")
                                continue
                            else:
                                # 添加referer避免防盗链
                                req = urllib.request.Request(url, headers={
                                    'Referer': 'https://www.doubao.com/',
                                    'User-Agent': 'Mozilla/5.0'
                                })
                                with urllib.request.urlopen(req, timeout=30) as resp:
                                    with open(save_path, 'wb') as f:
                                        f.write(resp.read())

                            dl = {'src': url, 'path': save_path}
                            downloaded.append(dl)
                            print(f"   ✅ {filename} ({img_info['w']}x{img_info['h']}px)")
                        except Exception as e:
                            pass
                else:
                    no_new_images_since += 5

                # 停止条件：有图片且连续30秒没新图
                if downloaded and no_new_images_since >= 30:
                    print(f"   ✅ 生成完成（{elapsed}秒）")
                    break

            except Exception as e:
                pass

            # 每30秒报告
            if elapsed > 0 and elapsed % 30 < 5:
                print(f"   ⏳ {elapsed}秒... (已下载{len(downloaded)}张)")

            # 检查生成是否在进行中
            try:
                # 豆包可能在显示"生成中"动画
                generating = page.locator('[class*="generating"], [class*="loading"], text=正在生成').first
                if generating.is_visible():
                    print(f"   🎨 豆包正在生成中...")
            except:
                pass

        # 报告
        print(f"\n{'=' * 60}")
        actual = [d for d in downloaded if isinstance(d, dict) and 'path' in d]
        if actual:
            print(f"✅ 生图完成！共 {len(actual)} 张")
            for d in actual:
                path = d['path']
                if os.path.exists(path):
                    size_kb = os.path.getsize(path) // 1024
                    print(f"   ▸ {os.path.basename(path)} ({size_kb}KB)")
            print(f"📁 {download_dir}")
        else:
            print(f"⚠️ 未检测到大尺寸生成图")
            print(f"   请手动保存图片到: {download_dir}")

        print(f"\n⏳ 浏览器保持 60 秒，可手动操作...")
        page.wait_for_timeout(60000)
        context.close()

if __name__ == '__main__':
    main()

