            if downloaded and no_new_secs >= 30:
                print(f"   ✅ 生成完成")
                break

            # 进度报告
            if elapsed % 30 <= 5:
                print(f"   ⏳ {elapsed}s ({len(downloaded)}张)")

            # 检查生成状态
            try:
                for status_text in ['正在生成', '生成中', 'creating']:
                    if page.locator(f'text={status_text}').first.is_visible():
                        print(f"   🎨 豆包{status_text}...")
