"""诊断：点击发送后页面发生了什么"""
from playwright.sync_api import sync_playwright
import os, time

USER_DATA_DIR = os.path.expanduser("~/Desktop/时尚项目/豆包浏览器数据")

with sync_playwright() as p:
    context = p.chromium.launch_persistent_context(
        USER_DATA_DIR, headless=False,
        viewport={'width': 1400, 'height': 900}, locale='zh-CN',
        args=['--disable-blink-features=AutomationControlled'],
    )
    context.add_init_script("""
        Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
    """)
    page = context.new_page()

    page.goto("https://www.doubao.com/chat/", wait_until='domcontentloaded', timeout=20000)
    page.wait_for_timeout(3000)

    if page.locator('text=登录').first.is_visible():
        print("⚠️ 请登录...")
        try:
            page.wait_for_selector('text=登录', state='hidden', timeout=120000)
        except:
            pass
    page.wait_for_timeout(2000)

    page.locator('text=图像生成').first.click()
    page.wait_for_timeout(3000)

    # 在编辑器中输入文字
    editor = page.locator('.ProseMirror').first
    editor.click()
    editor.type("你好，请生成一张图片测试", delay=20)
    page.wait_for_timeout(2000)

    # 截图：发送前
    page.screenshot(path=os.path.expanduser("~/Desktop/时尚项目/豆包截图_发送前.png"))

    # 找发送按钮并点击
    for btn in page.locator('button').all():
        try:
            box = btn.bounding_box()
            if box and 28 <= box['width'] <= 44 and 28 <= box['height'] <= 44:
                svg_c = btn.locator('svg').count()
                text = btn.text_content().strip()
                if svg_c > 0 and not text and box['x'] > 1150 and 830 < box['y'] < 850:
                    btn.click(force=True)
                    print(f"✅ 点击了发送按钮 at ({box['x']:.0f}, {box['y']:.0f})")
                    break
        except:
            continue

    # 等待
    page.wait_for_timeout(5000)

    # 截图：发送后
    page.screenshot(path=os.path.expanduser("~/Desktop/时尚项目/豆包截图_发送后.png"))

    # 检查聊天消息
    print("\n=== 聊天消息区域 ===")
    messages = page.evaluate("""() => {
        // 找聊天消息
        const allDivs = document.querySelectorAll('div');
        const msgs = [];
        for (const div of allDivs) {
            const text = div.textContent.trim();
            // 找包含测试文字的消息
            if (text.includes('你好，请生成一张图片测试')) {
                msgs.push({
                    tag: div.tagName,
                    class: div.className?.substring(0, 80) || '',
                    text: text.substring(0, 100)
                });
            }
        }
        // 也找豆包的回复
        for (const div of allDivs) {
            const text = div.textContent.trim();
            if (text.includes('生成') && text.length > 20 && text.length < 500) {
                msgs.push({
                    tag: div.tagName,
                    class: div.className?.substring(0, 80) || '',
                    text: text.substring(0, 200),
                    note: '(可能是豆包回复)'
                });
            }
        }
        return msgs;
    }""")

    if messages:
        for m in messages[:10]:
            print(f"   <{m['tag']}> {m.get('note','')}: {m['text'][:100]}")
    else:
        print("   未找到相关消息")

    # 检查页面中所有图片
    print("\n=== 页面图片 (>200px) ===")
    big_imgs = page.evaluate("""() => {
        const imgs = document.querySelectorAll('img');
        const res = [];
        for (const img of imgs) {
            if (img.naturalWidth > 200 || img.naturalHeight > 200) {
                res.push({
                    src: (img.src || '').substring(0, 80),
                    w: img.naturalWidth,
                    h: img.naturalHeight,
                    alt: img.alt || ''
                });
            }
        }
        return res;
    }""")
    for bi in big_imgs:
        print(f"   {bi['w']}x{bi['h']} src={bi['src'][:60]} alt={bi['alt'][:30]}")

    # 检查是否有 canvas
    canvas_count = page.evaluate('() => document.querySelectorAll("canvas").length')
    print(f"\n=== Canvas元素: {canvas_count} 个 ===")

    print("\n⏳ 浏览器保持 20 秒...")
    page.wait_for_timeout(20000)
    context.close()

