"""最终诊断：监控网络请求 + 完整DOM dump"""
from playwright.sync_api import sync_playwright
import os, time, json

USER_DATA_DIR = os.path.expanduser("~/Desktop/时尚项目/豆包浏览器数据")
OUTFIT_BASE = os.path.expanduser("~/Desktop/时尚项目/每日穿搭")

dirs = sorted([d for d in os.listdir(OUTFIT_BASE)
               if os.path.isdir(os.path.join(OUTFIT_BASE, d)) and not d.startswith('.')])
outfit_dir = os.path.join(OUTFIT_BASE, dirs[-1])
doubao_dir = os.path.join(outfit_dir, "豆包生图")
if not os.path.exists(doubao_dir):
    doubao_dir = outfit_dir

# 收集图片
images = []
for f in sorted(os.listdir(doubao_dir)):
    if f.startswith("人物_") and f.lower().endswith(('.jpg','.jpeg','.png')):
        images.append(os.path.join(doubao_dir, f)); break
for prefix in ['上衣_', '下装_', '鞋子_']:
    for f in sorted(os.listdir(doubao_dir)):
        if f.startswith(prefix) and f.lower().endswith(('.jpg','.jpeg','.png')):
            images.append(os.path.join(doubao_dir, f))
for f in sorted(os.listdir(doubao_dir)):
    if f.startswith('配饰_') and f.lower().endswith(('.jpg','.jpeg','.png')):
        images.append(os.path.join(doubao_dir, f))

prompt = open(os.path.join(doubao_dir, "豆包提示词.txt"), 'r', encoding='utf-8').read().strip()

# 收集网络请求中的图片URL
network_img_urls = set()

os.makedirs(USER_DATA_DIR, exist_ok=True)

with sync_playwright() as p:
    context = p.chromium.launch_persistent_context(
        USER_DATA_DIR, headless=False,
        viewport={'width': 1400, 'height': 900}, locale='zh-CN',
        args=['--disable-blink-features=AutomationControlled'],
    )
    context.add_init_script("""
        Object.defineProperty(navigator, 'webdriver', {get: () => undefined});
    """)
    page = context.new_page()

    # 监听网络响应
    def on_response(response):
        url = response.url
        content_type = response.headers.get('content-type', '')
        if 'image' in content_type or 'seedream' in url or 'generated' in url or 'output' in url:
            network_img_urls.add(url)
    page.on('response', on_response)

    # 1. 打开
    page.goto("https://www.doubao.com/chat/", wait_until='domcontentloaded', timeout=20000)
    page.wait_for_timeout(3000)
    if page.locator('text=登录').first.is_visible():
        print("⚠️ 请登录...")
        page.locator('text=登录').first.click()
        try:
            page.wait_for_selector('text=登录', state='hidden', timeout=120000)
        except:
            pass
    page.wait_for_timeout(2000)

    # 2. 图像生成
    page.locator('text=图像生成').first.click()
    page.wait_for_timeout(3000)

    # 3. 上传参考图
    for btn in page.locator('button').all():
        try:
            box = btn.bounding_box()
            if box and 30 <= box['width'] <= 42 and 30 <= box['height'] <= 42:
                if btn.locator('svg').count() > 0 and not btn.text_content().strip():
                    if 830 < box['y'] < 850 and box['x'] < 500:
                        with page.expect_file_chooser() as fc_info:
                            btn.click()
                        fc_info.value.set_files(images)
                        print(f"✅ 上传了 {len(images)} 张参考图")
                        break
        except:
            continue

    page.wait_for_timeout(8000)

    # 4. 填写提示词
    editor = page.locator('.ProseMirror').first
    editor.click()
    page.wait_for_timeout(500)
    editor.evaluate('el => el.innerHTML = ""')
    page.wait_for_timeout(300)
    editor.type(prompt, delay=10)
    page.wait_for_timeout(3000)

    # 5. 找发送按钮
    for btn in page.locator('button').all():
        try:
            box = btn.bounding_box()
            if box and 28 <= box['width'] <= 44 and 28 <= box['height'] <= 44:
                if btn.locator('svg').count() > 0 and not btn.text_content().strip():
                    if box['x'] > 1150 and 830 < box['y'] < 850:
                        btn.click(force=True)
                        print(f"✅ 点击发送")
                        break
        except:
            continue

    # 6. 等待并全面检测
    print("\n⏳ 等待生成（最多3分钟）...")
    start = time.time()

    while time.time() - start < 180:
        page.wait_for_timeout(10000)
        elapsed = int(time.time() - start)
        print(f"\n--- {elapsed}s ---")

        # 检查所有类型的图片元素
        all_images = page.evaluate("""() => {
            const results = [];

            // 标准 img 标签
            for (const img of document.querySelectorAll('img')) {
                if (img.naturalWidth > 100 || img.naturalHeight > 100) {
                    results.push({type: 'img', src: (img.src||'').substring(0,100), w: img.naturalWidth, h: img.naturalHeight});
                }
            }

            // background-image CSS
            for (const el of document.querySelectorAll('*')) {
                const bg = getComputedStyle(el).backgroundImage;
                if (bg && bg !== 'none' && bg.includes('url')) {
                    const url = bg.match(/url\\(["']?([^"']*)["']?\\)/)?.[1] || '';
                    if (url && url.length > 50) {
                        results.push({type: 'bg-image', src: url.substring(0,100), tag: el.tagName});
                    }
                }
            }

            // picture 元素
            for (const pic of document.querySelectorAll('picture')) {
                const sources = pic.querySelectorAll('source');
                for (const src of sources) {
                    const srcset = src.getAttribute('srcset') || '';
                    if (srcset) results.push({type: 'picture', src: srcset.substring(0,100)});
                }
            }

            // SVG image 元素
            for (const svgImg of document.querySelectorAll('svg image')) {
                const href = svgImg.getAttribute('href') || svgImg.getAttribute('xlink:href') || '';
                if (href) results.push({type: 'svg-image', src: href.substring(0,100)});
            }

            return results;
        }""")

        if all_images:
            print(f"  找到 {len(all_images)} 个图片元素:")
            for ai in all_images[-5:]:  # 只显示最后5个
                print(f"    [{ai['type']}] {ai['w']}x{ai['h']} {ai['src'][:70]}")

        # 检查聊天消息中是否包含生成结果
        gen_text = page.evaluate("""() => {
            const divs = document.querySelectorAll('div');
            const texts = [];
            for (const div of divs) {
                const t = div.textContent.trim();
                if ((t.includes('生成') && t.length > 50 && t.length < 300) || 
                    t.includes('图片已') || t.includes('已生成')) {
                    texts.push(t.substring(0, 200));
                }
            }
            return texts.slice(0, 5);
        }""")
        if gen_text:
            for gt in gen_text:
                print(f"   💬 {gt[:150]}")

        # 检查网络请求中是否有图片
        if network_img_urls:
            print(f"   🌐 {len(network_img_urls)} 个图片网络请求")
            for url in list(network_img_urls)[-3:]:
                print(f"      {url[:100]}")

        # 是否有新的内容出现
        if elapsed >= 60 and not all_images:
            print("   (无大图出现，继续等待...)")

    # 最终截图
    page.screenshot(path=os.path.expanduser("~/Desktop/时尚项目/豆包截图_最终.png"))
    print(f"\n📸 最终截图已保存")
    print(f"🌐 共捕获 {len(network_img_urls)} 个图片网络请求")

    page.wait_for_timeout(10000)
    context.close()

